// Intrusive, opt-in debugger observations of the shipped parseSnapshot body.
// No local values, object contents, forced GC or source replacements are used.
export async function traceNativeParseAllocations(socket, call, { minimumStringLength = 8000000 } = {}) {
  const scripts = [];
  const breakpoints = new Map();
  const report = {
    limitation:
      "Debugger pauses/deoptimization perturb execution. These are diagnostic boundary observations, not normal-run peak or timing proof. Allocation samples include objects collected by GC and are not live heap, exact allocation totals or billed CPU. No object contents are recorded.",
    boundaries: [],
    errors: [],
    unmatched_pauses: [],
    resolved_boundaries: [],
    pause_events: [],
  };
  const started = performance.now();
  let pending = Promise.resolve();
  const listener = ({ data }) => {
    const event = JSON.parse(data);
    if (event.method === "Debugger.scriptParsed") scripts.push(event.params);
    if (event.method !== "Debugger.paused") return;
    report.pause_events.push({
      reason: event.params.reason,
      hit_breakpoints: event.params.hitBreakpoints,
      location: event.params.callFrames?.[0]?.location,
      function_name: event.params.callFrames?.[0]?.functionName,
    });
    pending = pending.then(async () => {
      try {
        const location = event.params.callFrames?.[0]?.location;
        // workerd may omit hitBreakpoints or report a different boundary's ID.
        // Ground attribution only in the exact resolved script/line/column.
        const id = [...breakpoints].find(
          ([, boundary]) =>
            location?.scriptId === boundary.script_id &&
            location.lineNumber === boundary.generated_line - 1 &&
            location.columnNumber === boundary.generated_column,
        )?.[0];
        if (!id) {
          report.unmatched_pauses.push({
            reason: event.params.reason,
            hit_breakpoints: event.params.hitBreakpoints,
            location: event.params.callFrames?.[0]?.location,
            function_name: event.params.callFrames?.[0]?.functionName,
          });
          throw new Error("Unexpected debugger pause outside the selected parse boundaries");
        }
        const boundary = breakpoints.get(id);
        const frames = event.params.callFrames;
        if (!frames.some((frame) => frame.functionName === "parseSnapshot"))
          throw new Error("Selected boundary did not pause within parseSnapshot");
        const requested = performance.now() - started;
        const heap = await call("Runtime.getHeapUsage");
        const received = performance.now() - started;
        const allocationRequested = performance.now() - started;
        const { profile } = await call("HeapProfiler.getSamplingProfile");
        const allocationReceived = performance.now() - started;
        const allocations = [];
        const visit = (node, stack) => {
          const frames = [...stack, node.callFrame.functionName];
          if (node.selfSize > 0)
            allocations.push({ node_id: node.id, sampled_allocation_bytes: node.selfSize, stack: frames });
          for (const child of node.children) visit(child, frames);
        };
        visit(profile.head, []);
        report.boundaries.push({
          ...boundary,
          matched_by: "exact-resolved-location",
          heap: { requested_elapsed_ms: requested, received_elapsed_ms: received, ...heap },
          cumulative_allocations: {
            requested_elapsed_ms: allocationRequested,
            received_elapsed_ms: allocationReceived,
            allocations,
          },
        });
        await call("Debugger.removeBreakpoint", { breakpointId: id });
        breakpoints.delete(id);
      } catch (error) {
        report.errors.push(String(error));
      } finally {
        await call("Debugger.resume").catch((error) => report.errors.push(String(error)));
      }
    });
  };
  socket.addEventListener("message", listener);
  try {
    await call("Debugger.enable");
    let source;
    let scriptId;
    for (const script of scripts) {
      const { scriptSource } = await call("Debugger.getScriptSource", { scriptId: script.scriptId });
      if (!scriptSource.includes("async function parseSnapshot(")) continue;
      source = scriptSource;
      scriptId = script.scriptId;
      break;
    }
    if (!source) throw new Error("Shipped parseSnapshot script was not available to the debugger");
    const start = source.indexOf("async function parseSnapshot(");
    const end = source.indexOf("async function discoverSnapshotRequests(", start);
    if (end < 0) throw new Error("Could not bound the shipped parseSnapshot function");
    const markers = [
      ["before-canonicalization", "const observationBytes = utf8(canonicalJson(observationDocument));", start, end],
      [
        "after-canonical-string-before-utf8",
        "return encoder.encode(value);",
        source.indexOf("function utf8("),
        start,
        `value.length > ${minimumStringLength}`,
      ],
      ["after-utf8-before-digest", "const digest = await sha256(observationBytes);", start, end],
      ["after-r2-write", "if (observedToken && observedToken !== writeToken)", start, end],
    ];
    for (const [name, marker, from, through, condition] of markers) {
      const offset = source.indexOf(marker, from);
      if (from < 0 || offset < from || offset >= through) throw new Error(`Missing exact parse boundary: ${name}`);
      const lineNumber = source.slice(0, offset).split("\n").length - 1;
      const { breakpointId, actualLocation } = await call("Debugger.setBreakpoint", {
        location: { scriptId, lineNumber },
        ...(condition ? { condition } : {}),
      });
      if (actualLocation.lineNumber !== lineNumber) throw new Error(`Debugger moved boundary: ${name}`);
      report.resolved_boundaries.push({ name, breakpointId, actualLocation });
      breakpoints.set(breakpointId, {
        name,
        script_id: scriptId,
        generated_line: lineNumber + 1,
        generated_column: actualLocation.columnNumber,
      });
    }
    return async () => {
      await pending;
      report.unvisited_boundaries = [...breakpoints.values()].map(({ name }) => name);
      for (const id of breakpoints.keys()) await call("Debugger.removeBreakpoint", { breakpointId: id });
      await call("Debugger.disable");
      socket.removeEventListener("message", listener);
      return report;
    };
  } catch (error) {
    await call("Debugger.disable").catch(() => undefined);
    socket.removeEventListener("message", listener);
    throw error;
  }
}

test_source:
import assert from "node:assert/strict";
import test from "node:test";
import { Miniflare } from "miniflare";
import { traceNativeParseAllocations } from "./helpers/native-parse-allocation-trace.mjs";

test("parse allocation tracer identifies paused boundaries on actual workerd", async (t) => {
  const runtime = new Miniflare({
    inspectorPort: 0,
    modules: true,
    compatibilityDate: "2026-07-29",
    script: `
const encoder = new TextEncoder();
function utf8(value) {
  return encoder.encode(value);
}
function canonicalJson(value) { return JSON.stringify(value); }
async function sha256(value) { return crypto.subtle.digest("SHA-256", value); }
async function parseSnapshot() {
  const observationDocument = {calibration: "small"};
  const observationBytes = utf8(canonicalJson(observationDocument));
  const digest = await sha256(observationBytes);
  const writeToken = "x";
  const observedToken = await Promise.resolve("x");
  if (observedToken && observedToken !== writeToken) throw new Error("unexpected token");
  return observationBytes;
}
async function discoverSnapshotRequests() {}
export default {async fetch() { return new Response(await parseSnapshot()); }};`,
  });
  t.after(() => runtime.dispose());
  await runtime.ready;
  const url = await runtime.getInspectorURL();
  url.protocol = "http:";
  const targets = await (await fetch(new URL("/json", url))).json();
  const socket = new WebSocket(targets.find((target) => target.id.startsWith("core:user:")).webSocketDebuggerUrl);
  t.after(() => socket.close());
  await new Promise((resolve, reject) => {
    socket.addEventListener("open", resolve, { once: true });
    socket.addEventListener("error", reject, { once: true });
  });
  let sequence = 0;
  const call = (method, params) =>
    new Promise((resolve, reject) => {
      const id = ++sequence;
      const timer = setTimeout(() => {
        socket.removeEventListener("message", listener);
        reject(new Error(`Timeout: ${method}`));
      }, 5000);
      const listener = ({ data }) => {
        const result = JSON.parse(data);
        if (result.id !== id) return;
        clearTimeout(timer);
        socket.removeEventListener("message", listener);
        if (result.error) reject(new Error(result.error.message));
        else resolve(result.result);
      };
      socket.addEventListener("message", listener);
      socket.send(JSON.stringify({ id, method, params }));
    });
  await call("HeapProfiler.startSampling", {
    includeObjectsCollectedByMajorGC: true,
    includeObjectsCollectedByMinorGC: true,
  });
  const stop = await traceNativeParseAllocations(socket, call, { minimumStringLength: 0 });
  const response = await runtime.dispatchFetch("https://test.invalid/");
  assert.deepEqual(await response.json(), { calibration: "small" });
  const report = await stop();
  t.diagnostic(
    JSON.stringify({
      resolved: report.resolved_boundaries,
      pauses: report.pause_events,
      unmatched: report.unmatched_pauses,
      unvisited: report.unvisited_boundaries,
      visited: report.boundaries.map(({ name, generated_line, generated_column, matched_by }) => ({
        name,
        generated_line,
        generated_column,
        matched_by,
      })),
    }),
  );
  assert.deepEqual(report.errors, []);
  assert.deepEqual(report.unvisited_boundaries, []);
  assert.deepEqual(
    report.boundaries.map(({ name }) => name),
    ["before-canonicalization", "after-canonical-string-before-utf8", "after-utf8-before-digest", "after-r2-write"],
  );
});
